import { FlappyEngine, TICK_MS } from './engine.js';

const $ = id => document.getElementById(id);
const canvas = $('game');
const ctx = canvas.getContext('2d');
const W=1024, H=640, CELL=24, OX=32, OY=92;
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const keys=new Set();
let originals={}, engine, active=false, paused=false, sound=false, classic=false, audio, previous=0, accumulator=0, blend=1;
let pendingDirection=null, pendingFire=false;
let particles=[], flash=0, pressedDirection=null, fireHeld=false, lastStatus='', frameTime=0;
const DIRECTIONS={ArrowUp:[0,-1],KeyW:[0,-1],KeyE:[0,-1],ArrowDown:[0,1],KeyS:[0,1],KeyY:[0,1],ArrowLeft:[-1,0],KeyA:[-1,0],ArrowRight:[1,0],KeyD:[1,0]};
const palette={brick:'#3d5144',edge:'#6d8466',mortar:'#1d2c24',moss:'#7a9962',egg:'#d6fff3',glow:'#88e8c1',rock:'#a4a58e',player:'#f0d779',frog:'#b3d682',ghost:'#a7b6e6'};

canvas.width=W;canvas.height=H;
canvas.setAttribute('aria-label','Flappy, sektor 9. Pohyb šipkami nebo WASD, mezerník vystřelí houbičku, R nový pokus, P pauza.');
$('game-title').textContent='Flappy';
$('game-description').textContent='Jedno kuřátko. Jedno vajíčko. Dvě stě původních výzev.';
$('objective-title').innerHTML='Dostaňte vejce<br>do bezpečí.';
$('instruction-text').textContent='Přesuňte světlé vajíčko na zářící podložku. Kameny padají, duchové nespí a žáby vás pronásledují. Přemýšlejte o krok dopředu.';
$('objective-legend').innerHTML='<span class="legend-marker egg-marker"></span><span>Světlé vajíčko → zářící podložka</span>';
$('action-label').textContent='Uspávací houbička';
$('action-description').textContent='Nejdřív ji seberte, pak vystřelte';
$('touch-action').querySelector('span').textContent='STŘELA';
$('game-hint').innerHTML='<span aria-hidden="true">↳</span> <span id="stage-hint">Sektor 9 je připravený. Začněte šipkami.</span> <span class="hint-separator">·</span> <span class="mushroom-hint">✦</span> Houbičky: <strong id="ammo">0</strong>';
$('help-content').innerHTML=`<p>Vaším cílem je dopravit <strong>světlé vejce na světlou podložku</strong>. V této verzi začínáte přímo v původním sektoru 9.</p><dl class="help-list"><dt>↑ ↓ ← → / WASD</dt><dd>Volný pohyb ve čtyřech směrech. Fungují také původní klávesy E a Y.</dd><dt>Vejce a kameny</dt><dd>Tlačte je ze strany. Podléhají gravitaci a mohou rozdrtit vás i nepřátele. Tmavý kámen lze rozbít přitlačením k překážce nebo nárazem shora či zdola. Světlé vejce nerozbijete.</dd><dt>Mezerník</dt><dd>Vystřelí sebranou houbičku ve směru pohledu. Zasažená příšera na chvíli usne; padající vejce nebo kámen ji odstraní.</dd><dt>R · P · Enter</dt><dd>Nový pokus · pauza · pokračování po vyřešení sektoru.</dd></dl><p>Máte 5 životů a čas 1500. V nabídce STAGE můžete otevřít kterýkoli z 200 původních sektorů. Na telefonu použijte ovladač pod hrou.</p><p class="source-note">Nová webová implementace s daty původního FLAPPY+4 (VBG Software, 1988). <a href="https://pmd85.borik.net/wiki/Flappy" target="_blank" rel="noopener noreferrer">O původní hře ↗</a></p>`;
document.title='Flappy — PMD 85 webový remaster';
document.querySelector('meta[name="description"]').content='Hrajte Flappy pro PMD 85 v novém webovém zpracování. 200 původních sektorů; hra začíná rovnou na stage 9.';
const selector=$('stage-select');
selector.innerHTML=Array.from({length:200},(_,i)=>`<option value="${i+1}" ${i===8?'selected':''}>${String(i+1).padStart(2,'0')}</option>`).join('');
const graphics=document.createElement('button');graphics.className='control-button graphics-toggle';graphics.id='graphics-toggle';graphics.type='button';graphics.title='Přepnout grafiku';graphics.textContent='PMD režim';graphics.setAttribute('aria-pressed','false');
document.querySelector('.main-controls').append(graphics);
const ammoBadge=document.createElement('div');ammoBadge.className='ammo-badge';ammoBadge.innerHTML='<span aria-hidden="true">✦</span> <span class="sr-only">Houbičky: </span><span id="ammo-mobile">0</span>';
document.querySelector('.game-stats').prepend(ammoBadge);

function tone(freq=440,duration=.06,type='square',volume=.035,slide=0){
 if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,audio.currentTime);if(slide)osc.frequency.exponentialRampToValueAtTime(Math.max(20,slide),audio.currentTime+duration);gain.gain.setValueAtTime(volume,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration);}catch{}
}
function burst(x,y,color,count=12){if(reduceMotion)return;for(let i=0;i<count;i++)particles.push({x:OX+(x+1)*CELL,y:OY+(y+1)*CELL,vx:(Math.random()-.5)*2.6,vy:-Math.random()*2.7-1,life:1,color});}
function handleEvents(){for(const e of engine.events??[]){if(['break','crush','kill'].includes(e.type)){burst(e.x??engine.player.x,e.y??engine.player.y,e.type==='break'?'#c5b69a':'#accb85');tone(120,.09,'triangle',.05,40);}else if(['collect','pickup'].includes(e.type)){burst(e.x,e.y,'#e9ce88',7);tone(720,.13,'sine',.06,1300);}else if(['shoot','fire'].includes(e.type))tone(800,.08,'square',.025,190);else if(['death','dead'].includes(e.type)){flash=.4;burst(engine.player.x,engine.player.y,'#e9b28c',25);tone(220,.4,'sawtooth',.025,50);}else if(['win','won'].includes(e.type)){[0,1,2,3].forEach((n)=>setTimeout(()=>tone([523,659,784,1047][n],.2,'triangle',.09),n*110));burst(engine.goal.x,engine.goal.y-2,'#dbffb1',40);}}}
function syncUI(){
 selector.value=engine.stage;$('stage-hint').textContent=active?'Pozor na padající vejce a kameny.':`Sektor ${engine.stage} je připravený. Začněte šipkami.`;$('stage-number').textContent=String(engine.stage).padStart(2,'0');$('lives').textContent=engine.lives;$('moves').textContent=String(engine.moves).padStart(3,'0');$('timer').textContent=String(Math.ceil(engine.time)).padStart(4,'0');$('ammo').textContent=engine.ammo;$('ammo-mobile').textContent=engine.ammo;
 const status=engine.status==='won'?'SEKTOR VYŘEŠEN':engine.status==='gameover'?'KONEC HRY':engine.status==='dead'?'DALŠÍ POKUS…':paused?'POZASTAVENO':active?'HRAJETE • SEKTOR '+String(engine.stage).padStart(2,'0'):'PŘIPRAVENO • POHYB ŠIPKAMI';
 if(status!==lastStatus){$('status').textContent=status;lastStatus=status;}
 $('pause').setAttribute('aria-pressed',String(paused));$('pause').querySelector('span').textContent=paused?'Pokračovat':'Pauza';
 canvas.setAttribute('aria-label',`Flappy, sektor ${engine.stage}, ${engine.lives} životů, ${engine.ammo} houbiček. ${status}.`);
}
function start(){if(!engine||engine.status!=='playing')return;active=true;paused=false;canvas.focus({preventScroll:true});}
function reset(stage=engine.stage){engine.reset(stage);active=false;paused=false;accumulator=0;blend=1;particles=[];keys.clear();pressedDirection=null;fireHeld=false;pendingDirection=null;pendingFire=false;syncUI();canvas.focus({preventScroll:true});const url=new URL(location.href);if(stage===9)url.searchParams.delete('stage');else url.searchParams.set('stage',stage);history.replaceState({},'',url);}
function pause(){if(!engine||!active||engine.status!=='playing')return;paused=!paused;keys.clear();pressedDirection=null;fireHeld=false;pendingDirection=null;pendingFire=false;syncUI();canvas.focus({preventScroll:true});}
function continueStage(){if(engine.status==='won'){if(engine.stage<200){engine.advance();active=false;paused=false;accumulator=0;particles=[];syncUI();selector.value=engine.stage;}else reset(9);}else if(engine.status==='gameover')reset();else if(paused)pause();}
function getInput(){const ds=[...keys].filter(k=>DIRECTIONS[k]);const d=pressedDirection||DIRECTIONS[ds.at(-1)]||pendingDirection||[0,0];const fire=fireHeld||keys.has('Space')||pendingFire;pendingDirection=null;pendingFire=false;return{dx:d[0],dy:d[1],fire};}

window.addEventListener('keydown',e=>{
 const editing=['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName);if(editing||$('help-dialog').open||!engine)return;
 if(DIRECTIONS[e.code]||['Space','KeyP','KeyR','Enter','Escape'].includes(e.code)){e.preventDefault();if(e.code==='KeyR'&&!e.repeat){reset();return;}if(['KeyP','Escape'].includes(e.code)&&!e.repeat){pause();return;}if(e.code==='Enter'&&!e.repeat){continueStage();return;}if(engine.status==='won'||engine.status==='gameover'){if(e.code==='Space'&&!e.repeat)continueStage();return;}keys.add(e.code);if(DIRECTIONS[e.code])pendingDirection=DIRECTIONS[e.code];if(e.code==='Space')pendingFire=true;if(!paused)start();}
});window.addEventListener('keyup',e=>keys.delete(e.code));
window.addEventListener('blur',()=>{keys.clear();pressedDirection=null;fireHeld=false;if(active&&engine?.status==='playing'){paused=true;syncUI();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&active&&engine?.status==='playing'){paused=true;keys.clear();syncUI();}});
$('restart').addEventListener('click',()=>reset());$('pause').addEventListener('click',pause);selector.addEventListener('change',()=>reset(Number(selector.value)));
$('sound-toggle').addEventListener('click',()=>{sound=!sound;$('sound-toggle').setAttribute('aria-pressed',String(sound));$('sound-toggle').setAttribute('aria-label',sound?'Vypnout zvuk':'Zapnout zvuk');if(sound)tone(660,.12,'sine',.07);canvas.focus({preventScroll:true});});
graphics.addEventListener('click',()=>{classic=!classic;graphics.setAttribute('aria-pressed',String(classic));graphics.textContent=classic?'Nová grafika':'PMD režim';canvas.focus({preventScroll:true});});
$('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.game-panel').requestFullscreen();}catch{$('status').textContent='CELÁ OBRAZOVKA NENÍ DOSTUPNÁ';}});
let helpWasPaused=false;for(const id of ['help-button','more-help'])$(id).addEventListener('click',()=>{helpWasPaused=paused;if(active)paused=true;keys.clear();syncUI();$('help-dialog').showModal();});$('help-dialog').addEventListener('close',()=>{paused=helpWasPaused;syncUI();canvas.focus({preventScroll:true});});
for(const b of document.querySelectorAll('[data-direction]')){
 const dirs={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};
 b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);pressedDirection=dirs[b.dataset.direction];pendingDirection=pressedDirection;b.classList.add('is-pressed');start();});
 for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>{pressedDirection=null;b.classList.remove('is-pressed');});
}
$('touch-action').addEventListener('pointerdown',e=>{e.preventDefault();$('touch-action').setPointerCapture(e.pointerId);if(engine.status==='won'||engine.status==='gameover'){continueStage();return;}fireHeld=true;pendingFire=true;start();});for(const ev of ['pointerup','pointercancel','lostpointercapture'])$('touch-action').addEventListener(ev,()=>fireHeld=false);
canvas.addEventListener('click',()=>{if(engine.status==='won'||engine.status==='gameover'||paused)continueStage();else canvas.focus({preventScroll:true});});

function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}
function label(text,x,y,size=12,color='#9eb196',align='left'){ctx.fillStyle=color;ctx.font=`${size}px ui-monospace, SFMono-Regular, Consolas, monospace`;ctx.textAlign=align;ctx.fillText(text,x,y);}
function hashed(x,y){return ((x*73856093^y*19349663)>>>0)%100/100;}
function bitmap(name,x,y,w=CELL*2,h=CELL*2){const s=originals[name];if(!s)return;ctx.fillStyle='#56ee81';const pw=w/s.width,ph=h/s.height;for(let row=0;row<s.height;row++)for(let col=0;col<s.width;col++)if(s.rows[row][col]==='1')ctx.fillRect(x+col*pw,y+row*ph,Math.ceil(pw),Math.ceil(ph));}
function brick(x,y,w=CELL,h=CELL){
 if(classic){bitmap('brick',x,y,w,h);return;}
 const v=hashed(x,y);rounded(x+.5,y+.5,w-1,h-1,2,`rgb(${55+v*9},${72+v*10},${59+v*8})`);ctx.fillStyle='#71856588';ctx.fillRect(x+2,y+1,w-4,2);ctx.fillStyle='#192d24';ctx.fillRect(x+2,y+h-3,w-4,2);ctx.fillStyle='#91a97c22';ctx.fillRect(x+3,y+5,Math.max(3,w*.3),2);if(v>.73){ctx.fillStyle='#82a25d';ctx.fillRect(x+w*.24,y+2,5,2);ctx.fillRect(x+w*.4,y+3,3,3);}}
function drawBricks(){
 for(let y=0;y<20;y++)for(let x=0;x<40;x++){if(!engine.isBrick(x,y))continue;const bx=OX+x*CELL,by=OY+y*CELL;brick(bx,by);}
 for(let x=0;x<40;x++){brick(OX+x*CELL,OY-CELL);brick(OX+x*CELL,OY+20*CELL);}
}
function worldPosition(e){const t=reduceMotion?1:blend;return{x:OX+((e.prevX??e.x)+(e.x-(e.prevX??e.x))*t)*CELL,y:OY+((e.prevY??e.y)+(e.y-(e.prevY??e.y))*t)*CELL};}
function glow(x,y,r,color){if(classic)return;const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,color);g.addColorStop(1,'transparent');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2);}
function drawGoal(t){const x=OX+engine.goal.x*CELL,y=OY+engine.goal.y*CELL;glow(x+CELL,y-6,70,'#7ae3ae25');ctx.fillStyle=classic?'#56ff8c':'#ccffac';ctx.fillRect(x,y-3,CELL*2,6);ctx.fillStyle='#ccffac55';ctx.fillRect(x+5,y-8,CELL*2-10,3);if(!classic){ctx.strokeStyle='#a5e4ac55';ctx.lineWidth=1;for(let i=0;i<3;i++){let dy=(t/40+i*15)%45;ctx.globalAlpha=(1-dy/45)*.5;ctx.beginPath();ctx.moveTo(x+16,y-dy-6);ctx.lineTo(x+24,y-dy-14);ctx.lineTo(x+32,y-dy-6);ctx.stroke();}ctx.globalAlpha=1;}}
function drawEgg(e,t){const p=worldPosition(e);if(classic){bitmap('egg',p.x,p.y);return;}const x=p.x+CELL,y=p.y+CELL;glow(x,y,47,'#9de9d222');ctx.save();ctx.translate(x,y);const scale=e.falling&&!reduceMotion?1.035:1;ctx.scale(1,scale);ctx.beginPath();ctx.moveTo(0,-21);ctx.bezierCurveTo(13,-21,21,3,19,12);ctx.bezierCurveTo(17,27,-17,27,-19,12);ctx.bezierCurveTo(-21,3,-13,-21,0,-21);ctx.closePath();if(classic)ctx.fillStyle='#66ff8e';else{const g=ctx.createLinearGradient(-17,-15,17,18);g.addColorStop(0,'#f3fff0');g.addColorStop(.5,'#d8f6d7');g.addColorStop(1,'#7bbfb0');ctx.fillStyle=g;}ctx.fill();if(!classic){ctx.lineWidth=2;ctx.strokeStyle='#e4ffe6';ctx.stroke();ctx.fillStyle='#fff9';ctx.beginPath();ctx.ellipse(-7,-8,4,7,.3,0,Math.PI*2);ctx.fill();}ctx.restore();}
function drawRock(e){const p=worldPosition(e);if(classic){bitmap('rock',p.x,p.y);return;}const x=p.x+CELL,y=p.y+CELL;ctx.save();ctx.translate(x,y);ctx.beginPath();ctx.moveTo(-13,-21);ctx.lineTo(9,-23);ctx.lineTo(21,-9);ctx.lineTo(20,15);ctx.lineTo(8,22);ctx.lineTo(-14,19);ctx.lineTo(-21,6);ctx.lineTo(-19,-11);ctx.closePath();ctx.fillStyle=classic?'#2c8847':'#8f9580';ctx.fill();ctx.strokeStyle=classic?'#66ff8e':'#c1c3a0';ctx.lineWidth=2;ctx.stroke();ctx.beginPath();ctx.moveTo(-15,-10);ctx.lineTo(-2,-17);ctx.lineTo(12,-10);ctx.lineTo(5,1);ctx.lineTo(17,10);ctx.moveTo(-2,-17);ctx.lineTo(-5,-4);ctx.lineTo(-14,3);ctx.lineTo(-6,14);ctx.strokeStyle=classic?'#66ff8e':'#626f5b';ctx.lineWidth=2;ctx.stroke();if(!classic){ctx.fillStyle='#cad1aa77';ctx.fillRect(-10,-13,5,3);ctx.fillRect(8,10,4,2);}ctx.restore();}
function drawPlayer(e,t){const p=worldPosition(e);if(classic){bitmap({left:'playerLeft',right:'playerRight',up:'playerUp',down:'playerDown'}[e.dir]||'playerDown',p.x,p.y);return;}const x=p.x+CELL,y=p.y+CELL;const walking=e.x!==e.prevX||e.y!==e.prevY;ctx.save();ctx.translate(x,y+(walking&&!reduceMotion?Math.sin(t/55)*1.3:0));if(engine.status==='dead')ctx.rotate(Math.PI*.5);let facing=typeof e.dir==='object'?(e.dir.dx??e.dir.x??1):e.dir;ctx.scale(facing===-1||facing==='left'?-1:1,1);if(classic){ctx.fillStyle='#72ff94';ctx.beginPath();ctx.roundRect(-19,-18,37,38,10);ctx.fill();ctx.fillRect(-20,12,8,11);ctx.fillRect(10,12,8,11);ctx.fillStyle='#052b10';ctx.fillRect(2,-11,5,8);ctx.fillRect(12,-11,4,8);ctx.fillStyle='#72ff94';ctx.fillRect(-6,-23,7,8);}else{ctx.fillStyle='#141c16';ctx.beginPath();ctx.ellipse(0,22,20,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#cc9d4e';rounded(-16,16,12,7,3,'#d7a451');rounded(6,16,12,7,3,'#d7a451');const g=ctx.createLinearGradient(-17,-20,15,22);g.addColorStop(0,'#fff0a6');g.addColorStop(.6,'#ecd074');g.addColorStop(1,'#cda854');ctx.fillStyle=g;ctx.beginPath();ctx.roundRect(-19,-19,38,40,[15,16,13,11]);ctx.fill();ctx.strokeStyle='#fae5a1';ctx.lineWidth=1.5;ctx.stroke();ctx.fillStyle='#efc166';ctx.beginPath();ctx.ellipse(-8,6,8,10,-.4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f4dc89';ctx.beginPath();ctx.moveTo(-5,-18);ctx.lineTo(-4,-25);ctx.lineTo(2,-20);ctx.lineTo(7,-24);ctx.lineTo(7,-17);ctx.fill();ctx.fillStyle='#253523';ctx.beginPath();ctx.ellipse(8,-6,3.2,4.6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff6';ctx.fillRect(8,-8,2,2);ctx.fillStyle='#dc9751';ctx.beginPath();ctx.moveTo(17,-5);ctx.lineTo(26,0);ctx.lineTo(17,5);ctx.fill();ctx.fillStyle='#e7a27499';ctx.beginPath();ctx.ellipse(10,4,5,3,0,0,Math.PI*2);ctx.fill();}ctx.restore();}
function drawGhost(e,t){const p=worldPosition(e);if(classic){bitmap('ghost',p.x,p.y);return;}const x=p.x+CELL,y=p.y+CELL;ctx.save();ctx.translate(x,y+(!reduceMotion?Math.sin(t/230+e.x)*2:0));ctx.fillStyle=classic?'#66ff8e':e.sleep>0?'#697c83':'#a9b9e4';ctx.beginPath();ctx.moveTo(-17,19);ctx.lineTo(-17,-5);ctx.bezierCurveTo(-17,-26,17,-26,17,-5);ctx.lineTo(17,19);ctx.lineTo(8,13);ctx.lineTo(0,20);ctx.lineTo(-8,14);ctx.closePath();ctx.fill();if(!classic){ctx.fillStyle='#d4dff08a';ctx.beginPath();ctx.ellipse(-8,-9,4,7,.3,0,Math.PI*2);ctx.fill();}ctx.fillStyle='#253743';if(e.sleep>0){ctx.fillRect(-7,-2,6,2);ctx.fillRect(5,-2,6,2);label('z',14,-23,12,'#c5dbcb');}else{ctx.fillRect(-7,-7,5,9);ctx.fillRect(5,-7,5,9);}ctx.restore();}
function drawFrog(e,t){const p=worldPosition(e);if(classic){bitmap('frog',p.x,p.y);return;}const x=p.x+CELL,y=p.y+CELL;ctx.save();ctx.translate(x,y);const c=classic?'#66ff8e':e.sleep>0?'#718574':'#a2c779';rounded(-19,-9,38,29,10,c);rounded(-18,-20,15,20,6,c);rounded(4,-20,15,20,6,c);rounded(-22,15,16,7,3,c);rounded(7,15,16,7,3,c);ctx.fillStyle=classic?'#062911':'#263b2a';if(e.sleep>0){ctx.fillRect(-14,-9,7,2);ctx.fillRect(8,-9,7,2);label('z',17,-24,12,'#c5dbcb');}else{ctx.beginPath();ctx.ellipse(-10,-11,3,5,0,0,Math.PI*2);ctx.ellipse(11,-11,3,5,0,0,Math.PI*2);ctx.fill();}ctx.strokeStyle=classic?'#062911':'#526f42';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-9,5);ctx.quadraticCurveTo(0,12,10,5);ctx.stroke();ctx.restore();}
function drawMushroom(e,t){if(classic){bitmap('mushroom',OX+e.x*CELL,OY+e.y*CELL,CELL,CELL);return;}const x=OX+(e.x+.5)*CELL,y=OY+(e.y+.5)*CELL;glow(x,y,23,'#eece7320');ctx.fillStyle=classic?'#66ff8e':'#e8d5a3';rounded(x-3,y,6,12,2,ctx.fillStyle);ctx.fillStyle=classic?'#66ff8e':'#da9574';ctx.beginPath();ctx.moveTo(x-11,y+1);ctx.bezierCurveTo(x-11,y-16,x+11,y-16,x+11,y+1);ctx.closePath();ctx.fill();if(!classic){ctx.fillStyle='#ffe6c3';ctx.fillRect(x-5,y-6,3,3);ctx.fillRect(x+3,y-4,3,3);}}
function drawOverlay(title,subtitle,action,kind='normal'){
 ctx.fillStyle='#0a1713d9';ctx.fillRect(OX,OY,960,480);const cx=W/2,cy=H/2;rounded(cx-230,cy-84,460,178,8,'#1e3028','#637957');label(kind==='win'?'✦  VÝBORNĚ  ✦':'FLAPPY / PMD 85',cx,cy-45,12,'#c3db98','center');ctx.textAlign='center';ctx.font='bold 32px Helvetica,Arial,sans-serif';ctx.fillStyle='#eef0d8';ctx.fillText(title,cx,cy-2);label(subtitle,cx,cy+29,12,'#a9b99f','center');label(action,cx,cy+64,11,'#d0ed82','center');}
function draw(time){
 frameTime=time;ctx.clearRect(0,0,W,H);ctx.fillStyle=classic?'#001b09':'#111e18';ctx.fillRect(0,0,W,H);if(!classic){const g=ctx.createRadialGradient(W/2,200,30,W/2,350,650);g.addColorStop(0,'#233b2c');g.addColorStop(1,'#0c1612');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);for(let i=0;i<48;i++){const x=32+hashed(i,3)*960,y=80+hashed(i,7)*490;ctx.fillStyle=`rgba(189,214,148,${.025+hashed(i,8)*.07})`;ctx.fillRect(x,y,2,2);}}
 label('SEKTOR '+String(engine.stage).padStart(2,'0')+' / 200',OX+2,42,13,classic?'#5dff8d':'#a4b394');label('PŮVODNÍ MÍSTNOST · NOVÁ VÝZVA',W-OX,42,11,classic?'#5dff8d':'#82947b','right');
 if(!classic){ctx.strokeStyle='#74946812';ctx.lineWidth=1;for(let x=1;x<40;x++){ctx.beginPath();ctx.moveTo(OX+x*CELL,OY);ctx.lineTo(OX+x*CELL,OY+480);ctx.stroke();}for(let y=1;y<20;y++){ctx.beginPath();ctx.moveTo(OX,OY+y*CELL);ctx.lineTo(OX+960,OY+y*CELL);ctx.stroke();}}
 drawBricks();drawGoal(time);
 for(const m of engine.mushrooms)if(m.alive!==false)drawMushroom(m,time);
 for(const o of engine.objects)if(o.alive!==false){if(o.kind==='egg')drawEgg(o,time);else drawRock(o);}
 for(const e of engine.enemies)if(e.alive!==false){if(e.kind==='frog')drawFrog(e,time);else drawGhost(e,time);}
 for(const s of engine.shots??[]){if(s.alive===false)continue;const p=worldPosition(s);glow(p.x+12,p.y+12,22,'#e5cc8866');ctx.fillStyle=classic?'#5dff8d':'#f1d99b';ctx.fillRect(p.x+7,p.y+8,12,7);}
 if(engine.status!=='gameover')drawPlayer(engine.player,time);
 if(!reduceMotion){for(const p of particles){p.x+=p.vx;p.y+=p.vy;p.vy+=.07;p.life-=.02;ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,4,4);}particles=particles.filter(p=>p.life>0);ctx.globalAlpha=1;}
 label('VBG SOFTWARE 1988',OX+2,H-15,10,classic?'#3cbd63':'#637a61');label(classic?'PMD / MONOCHROME':'WEB REMASTER',W-OX,H-15,10,classic?'#3cbd63':'#637a61','right');
 if(engine.status==='won')drawOverlay(engine.stage===200?'Všech 200 za vámi!':'Sektor dokončen',engine.stage===200?'Flappy je v bezpečí. Děkujeme za hru.':'Vajíčko našlo své místo.',engine.stage===200?'ENTER / KLIKNUTÍ — ZNOVU OD 9':'ENTER / KLIKNUTÍ — DALŠÍ SEKTOR','win');
 else if(engine.status==='gameover')drawOverlay('Ještě jeden pokus?', 'Pět životů pryč. Každý pokus vás posune.', 'R / ENTER / KLIKNUTÍ — HRÁT ZNOVU');
 else if(paused)drawOverlay('Chvilka na rozmyšlenou', 'Váš sektor počká.', 'P / KLIKNUTÍ — POKRAČOVAT');
 else if(engine.status==='dead'){ctx.fillStyle='#442c1930';ctx.fillRect(OX,OY,960,480);}
 if(flash>0&&!reduceMotion){ctx.fillStyle=`rgba(233,148,111,${flash})`;ctx.fillRect(OX,OY,960,480);flash=Math.max(0,flash-.025);}
}
function frame(now){const dt=Math.min(now-previous,150);previous=now;if(engine){if(active&&!paused&&engine.status!=='won'&&engine.status!=='gameover'){accumulator+=dt;while(accumulator>=TICK_MS){engine.step(getInput());handleEvents();accumulator-=TICK_MS;syncUI();}blend=Math.min(1,accumulator/TICK_MS);}else blend=1;draw(now);}requestAnimationFrame(frame);}
async function boot(){try{const response=await fetch('./levels.json');if(!response.ok)throw new Error('Data úrovní nejsou dostupná');const data=await response.json();const spriteResponse=await fetch('./sprites.json');if(spriteResponse.ok)originals=await spriteResponse.json();const requested=Number(new URL(location.href).searchParams.get('stage')||9);const stage=Number.isInteger(requested)&&requested>=1&&requested<=200?requested:9;engine=new FlappyEngine(data,stage);syncUI();requestAnimationFrame(frame);}catch(err){$('status').textContent='HRU SE NEPODAŘILO NAČÍST';ctx.fillStyle='#112018';ctx.fillRect(0,0,W,H);label('Hru se nepodařilo načíst.',W/2,H/2,22,'#f0e6cd','center');label('Obnovte stránku nebo spusťte projekt přes npm start.',W/2,H/2+38,13,'#b4bba4','center');console.error(err);}}
boot();
